#include <stdio.h>

int main() {
    int a[] = {0, 2, 0, 4, 5};
    int pos = 0;
    for (int i = 0; i < 5; i++) {
        if (a[i] != 0) {
            int temp = a[pos];
            a[pos] = a[i];
            a[i] = temp;
            pos++;
        }
    }
    for (int i = 0; i < 5; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    return 0;
}
